INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Kalkulation > Stundensatz- und Dienstleistungskalkulationen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Stundensatzkalkulation immer alle Kostenarten berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Vollständige Kosten sind Grundlage für realistische Sätze"}, {"text": "Nein", "correct": false, "because": "Kosten sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Dienstleistungskalkulation ohne Rücksicht auf die Arbeitszeit erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Arbeitszeit ist zentraler Kostenfaktor"}, {"text": "Ja", "correct": false, "because": "Zeit beeinflusst Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Stundensatz immer gleich für alle Dienstleistungen eines Unternehmens?', 2, '[{"text": "Nein", "correct": true, "because": "Variiert je nach Qualifikation und Aufgabe"}, {"text": "Ja", "correct": false, "because": "Unterschiede sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Gemeinkosten in der Stundensatzkalkulation ignoriert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Gemeinkosten sind Teil der Gesamtkosten"}, {"text": "Ja", "correct": false, "because": "Einfluss auf Stundensatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Dienstleistungskalkulation unabhängig vom Marktpreis?', 2, '[{"text": "Nein", "correct": true, "because": "Marktpreise beeinflussen Wettbewerbsfähigkeit"}, {"text": "Ja", "correct": false, "because": "Marktorientierung nötig"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Stundensatzkalkulation am wichtigsten?', 3, '[{"text": "Gesamtkosten", "correct": true, "because": "Basis für realistische Kalkulation"}, {"text": "Farbe des Büros", "correct": false, "because": "Ästhetisch, nicht relevant"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart wird direkt in den Stundensatz eingerechnet?', 2, '[{"text": "Lohnkosten", "correct": true, "because": "Hauptbestandteil der Arbeitszeit"}, {"text": "Marketingkosten", "correct": false, "because": "Indirekt"}, {"text": "Transportkosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird oft für die Dienstleistungskalkulation verwendet?', 2, '[{"text": "Zuschlagskalkulation", "correct": true, "because": "Berücksichtigt Gemeinkosten"}, {"text": "Abschreibung", "correct": false, "because": "Für Anlagen"}, {"text": "Lagerhaltung", "correct": false, "because": "Für Waren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt beeinflusst die Dienstleistungskalkulation maßgeblich?', 3, '[{"text": "Arbeitszeit", "correct": true, "because": "Kern der Kostenberechnung"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferfrist", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Stundensatzkalkulation?', 2, '[{"text": "Kostendeckung", "correct": true, "because": "Sichert wirtschaftlichen Betrieb"}, {"text": "Minimale Preise", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Abrechnung", "correct": false, "because": "Sekundär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten fließen in die Stundensatzkalkulation ein?', 4, '[{"text": "Lohnkosten", "correct": true, "because": "Direkte Arbeitskosten"}, {"text": "Gemeinkosten", "correct": true, "because": "Indirekte Kosten"}, {"text": "Materialkosten", "correct": true, "because": "Für Dienstleistungen relevant"}, {"text": "Werbekosten", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Dienstleistungskalkulation?', 3, '[{"text": "Arbeitszeit", "correct": true, "because": "Hauptkostenfaktor"}, {"text": "Qualifikation", "correct": true, "because": "Beeinflusst Stundensatz"}, {"text": "Marktpreis", "correct": true, "because": "Wettbewerbsfähigkeit"}, {"text": "Farbe des Büros", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine genaue Stundensatzkalkulation?', 3, '[{"text": "Kostentransparenz", "correct": true, "because": "Klarheit über Ausgaben"}, {"text": "Wettbewerbsfähigkeit", "correct": true, "because": "Realistische Preise"}, {"text": "Gewinnsicherung", "correct": true, "because": "Deckt Kosten"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für die Stundensatzkalkulation wichtig?', 4, '[{"text": "Lohnkosten", "correct": true, "because": "Direkte Kosten"}, {"text": "Gemeinkostenzuschlag", "correct": true, "because": "Indirekte Kosten"}, {"text": "Arbeitsstunden", "correct": true, "because": "Zeitbasis"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Dienstleistungskalkulation auftreten?', 3, '[{"text": "Unrealistische Zeitangaben", "correct": true, "because": "Verfälscht Kosten"}, {"text": "Fehlende Gemeinkosten", "correct": true, "because": "Unterdeckung"}, {"text": "Marktignoranz", "correct": true, "because": "Unwettbewerbsfähig"}, {"text": "Geringe Lautstärke", "correct": false, "because": "Irrelevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Lohnkosten sind ein Kernbestandteil der Stundensatzkalkulation. b) Gemeinkosten können ignoriert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lohn ja, Gemeinkosten wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitszeit ist ein zentraler Faktor der Dienstleistungskalkulation. b) Der Stundensatz ist für alle Dienstleistungen gleich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeit ja, Stundensatz variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Zuschlagskalkulation berücksichtigt Gemeinkosten. b) Marktpreise sind bei der Kalkulation irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zuschlag ja, Markt wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine genaue Stundensatzkalkulation sichert den Gewinn. b) Materialkosten sind bei Dienstleistungen immer entscheidend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gewinn ja, Material variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Dienstleistungskalkulation berücksichtigt Qualifikationen. b) Kostendeckung ist kein Ziel der Kalkulation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualifikation ja, Deckung wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

